Core Telehealth Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(core_telehealth_service, "Core Telehealth Service") {
    Component(consultation_manager, "Consultation Manager", "Go / Spring Boot", "Manages telehealth consultation sessions between patients and clinicians.")
    Component(consent_privacy_enforcement, "Consent & Privacy Enforcement", "Go / Spring Boot", "Validates patient consent and enforces privacy compliance.")
    Component(prescription_coordinator, "Prescription Coordinator", "Go / Spring Boot", "Coordinates e-prescriptions across regional networks.")
    Component(symptom_assessment_logger, "Symptom Assessment Logger", "Go / Spring Boot", "Logs and persists symptom assessment details and audit trails.")
}

Rel(consultation_manager, consent_privacy_enforcement, "Validates patient consent", "In-memory function call")

@enduml

WebRTC SFU Video Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(webRTC_sfu_video_service, "WebRTC SFU Video Service") {
    Component(Signaling_Room_Manager, "Signaling & Room Manager", "Node.js / TypeScript", "Manages signaling via gRPC and controls room sessions and tracks.")
    Component(Media_Router_Node, "Media Router Node", "Mediasoup Worker in C++ / Node.js", "Powers selective forwarding and simulcast stream adaptation.")
    Component(Bandwidth_Adaptation_Controller, "Bandwidth Adaptation Controller", "C++", "Guarantees resilient, degraded-mode consultations for unstable rural connections by processing media telemetry.")
}

Rel(Signaling_Room_Manager, Media_Router_Node, "Controls media tracks", "IPC (Local Pipe)")
Rel(Media_Router_Node, Bandwidth_Adaptation_Controller, "Feeds telemetry", "Internal Function Call")

@enduml

FHIR Event Bus.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(fhiring_event_bus, "FHIR Event Bus") {
    Component(EventRouter, "Event Router", "GCP Pub/Sub", "Publishes and routes regional FHIR bundles.")
    Component(FHiredSchemaValidator, "FHired Schema Validator", "HL7 FHIR", "Validates schema compliance of event payloads.")
    Component(AuditLedgerSink, "Audit Ledger Sink", "Go / GCP Pub/Sub", "Forwards event metadata for tracing and audit purposes.")
    Component(RegionalIsolationEnforcer, "Regional Isolation Enforcer", "Go", "Validates data residency before queuing events.")
}

Rel(EventRouter, RegionalIsolationEnforcer, "Validates residency before queuing", "Internal function call")
Rel(EventRouter, AuditLedgerSink, "Forwards event metadata for tracing", "Internal gRPC")

@startuml
